 function placeAt(data){if(!currentPiece()){const [id,x,y]=data.split(':'),b=E.board(me(),id),c=b?.cells[+y*b.w+(+x)];if(c&&me().storage.includes(b)){ui.source=c.id;ui.rotation=0;ui.flip=false;render();}else toast('먼저 가공하거나 보관소의 조각을 선택하세요.');return;}const [id,x,y]=data.split(':');dispatch('place',{source:ui.source,board:id,x:+x,y:+y,rotation:ui.rotation,flip:ui.flip});}
 function markPreview(data){app.querySelectorAll('.valid-preview,.invalid-preview').forEach(c=>c.classList.remove('valid-preview','invalid-preview'));const p=currentPiece();if(!p)return;const [id,x,y]=data.split(':'),piece={...p,rotation:ui.rotation,flip:ui.flip},ok=E.canPlace(me(),piece,id,+x,+y,p.id);for(const [a,b]of E.pieceCells(piece)){const cell=app.querySelector(`[data-cell="${id}:${+x+a}:${+y+b}"]`);cell?.classList.add(ok?'valid-preview':'invalid-preview');}}

 function placeBag(x,y){if(ui.splitFood){dispatch('splitFood',{id:ui.splitFood,x,y});return;}if(ui.resourceHeld){dropResource(ui.resourceHeld,'bag',x,y);return;}const i=bagSelection();if(!i)return;dispatch(ui.bagItem?'bagMove':'placeLoot',{id:ui.bagItem,x,y,rotation:ui.bagRotation,flip:ui.bagFlip});}
 function bagPoint(e){const r=$('.bag-grid').getBoundingClientRect();return [Math.floor((e.clientX-r.left)/r.width*5),Math.floor((e.clientY-r.top)/r.height*5)];}
 function previewBag(x,y){const layer=$('.bag-preview'),i=bagSelection();if(!layer||!i)return;const ok=E.bagFits(bagOwner(),i,x,y);layer.innerHTML=E.itemCells(i).map(([a,b])=>`<i class="${ok?'valid-preview':'invalid-preview'}" style="left:${(x+a)*20}%;top:${(y+b)*20}%"></i>`).join('');}
 function installDrag(){app.querySelectorAll('[data-cell]').forEach(c=>{c.addEventListener('mouseenter',()=>markPreview(c.dataset.cell));c.addEventListener('mouseleave',()=>app.querySelectorAll('.valid-preview,.invalid-preview').forEach(c=>c.classList.remove('valid-preview','invalid-preview')));c.addEventListener('dragover',e=>{e.preventDefault();markPreview(c.dataset.cell);});c.addEventListener('drop',e=>{e.preventDefault();placeAt(c.dataset.cell);});});app.querySelectorAll('[data-piece]').forEach(el=>el.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain','piece')));
 app.querySelectorAll('[data-card]').forEach(el=>{el.addEventListener('dragstart',e=>{e.dataTransfer.setData('application/x-dino-card',el.dataset.card);e.dataTransfer.setData('text/plain','card:'+el.dataset.card);e.dataTransfer.effectAllowed='move';$('.board-area')?.classList.add('card-drag-over');});el.addEventListener('dragend',()=>$('.board-area')?.classList.remove('card-drag-over'));});
 const board=$('.board-area');board?.addEventListener('dragover',e=>{if([...e.dataTransfer.types].includes('application/x-dino-card')){e.preventDefault();e.dataTransfer.dropEffect='move';board.classList.add('card-drag-over');}});board?.addEventListener('drop',e=>{const n=e.dataTransfer.getData('application/x-dino-card');if(n!==''){e.preventDefault();e.stopPropagation();pickCard(+n);}});
 app.querySelectorAll('[data-item],[data-loot]').forEach(el=>el.addEventListener('dragstart',e=>{const previous=ui.bagItem;ui.bagItem=el.dataset.item||null;const item=ui.bagItem?bagOwner().bag.find(i=>i.id===ui.bagItem):g.loot[0];if((el.dataset.item&&previous!==el.dataset.item)||(!el.dataset.item&&previous)){ui.bagRotation=item.rotation||0;ui.bagFlip=!!item.flip;}e.dataTransfer.setData('application/x-dino-item',ui.bagItem||'loot');e.dataTransfer.setData('text/plain',ui.bagItem||'loot');e.dataTransfer.effectAllowed='move';}));
 const grid=$('.bag-grid');if(grid){grid.addEventListener('mousemove',e=>previewBag(...bagPoint(e)));grid.addEventListener('mouseleave',()=>{$('.bag-preview').innerHTML='';});grid.addEventListener('dragover',e=>{if([...e.dataTransfer.types].includes('application/x-dino-item')){e.preventDefault();previewBag(...bagPoint(e));}});grid.addEventListener('drop',e=>{if(e.dataTransfer.getData('application/x-dino-item')){e.preventDefault();placeBag(...bagPoint(e));}});}
 }
 function installMap(){const svg=$('#map');if(!svg)return;let drag=null,moved=false;svg.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('[data-hex]'))return;drag={x:e.clientX,y:e.clientY,px:ui.panX,py:ui.panY};moved=false;svg.setPointerCapture(e.pointerId);svg.classList.add('panning');});svg.addEventListener('pointermove',e=>{if(!drag)return;const ratio=1/(svg.getScreenCTM()?.a||1);ui.panX=drag.px+(e.clientX-drag.x)*ratio;ui.panY=drag.py+(e.clientY-drag.y)*ratio;svg.firstElementChild.setAttribute('transform',`translate(${410+ui.panX} ${285+ui.panY}) scale(${ui.zoom})`);moved=true;});svg.addEventListener('pointerup',()=>{drag=null;svg.classList.remove('panning');});svg.addEventListener('wheel',e=>{e.preventDefault();ui.zoom=Math.max(.35,Math.min(2.3,ui.zoom+(e.deltaY<0?.07:-.07)));svg.firstElementChild.setAttribute('transform',`translate(${410+ui.panX} ${285+ui.panY}) scale(${ui.zoom})`);},{passive:false});}
 $('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>3e6)throw new Error('저장 파일이 너무 큽니다.');const s=JSON.parse(await file.text());cancelMotion();if(!validSave(s))throw new Error('호환되는 타임 투 다이노 저장 파일이 아닙니다.');history.push(g);if(s.version===1)localStorage.setItem(SAVE+'-backup',JSON.stringify(s));g=E.migrateSave(s);Object.assign(ui,{resourceHeld:null,chooser:false,bagItem:null,bagRotation:0,bagFlip:false,level:1,intro:null,setup:false,modal:null,pass:false,selectedCard:null,tile:me().pos,mode:'view',source:'pending',hideEnd:false,battleCards:[],panX:0,panY:0});save();render();toast('원정을 불러왔습니다.');}catch(err){toast(err.message);}e.target.value='';});
 document.addEventListener('keydown',e=>{if(resourceDrag){if(e.key==='Escape'){cancelResourceDrag();return;}if(['r','f'].includes(e.key.toLowerCase())){e.preventDefault();if(e.key.toLowerCase()==='r')ui.bagRotation=(ui.bagRotation+1)%4;else ui.bagFlip=!ui.bagFlip;if(resourceDrag.ghost)resourceDrag.ghost.innerHTML=itemShape({...resourceItem(resourceDrag.source),rotation:ui.bagRotation,flip:ui.bagFlip},36);return;}}if(ui.recipeOpen){if(e.key==='Escape'){ui.recipeOpen=false;render();afterMotion(()=>$('[data-do="recipes"]')?.focus({preventScroll:true}));}if(e.key==='Tab'){const nodes=[...app.querySelectorAll('.recipe-board button:not(:disabled)')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;}if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='Escape'&&!g.pending.length&&!g.battle){ui.eventInspect=null;ui.splitFood=null;ui.aircraftPreview=false;ui.resourceHeld=null;ui.modal=null;ui.mode='view';ui.chooser=false;ui.selectedCard=null;ui.bagItem=null;render();}if(!ui.modal&&!g.battle&&bagSelection()&&['r','f'].includes(e.key.toLowerCase())){if(e.key.toLowerCase()==='r')ui.bagRotation=(ui.bagRotation+1)%4;else ui.bagFlip=!ui.bagFlip;render();return;}if((ui.modal==='camp'||g.pending.length)&&currentPiece()){if(e.key.toLowerCase()==='r'){ui.rotation=(ui.rotation+1)%4;render();}if(e.key.toLowerCase()==='f')toast('건설 조각은 회전만 가능합니다.');return;}if((!ui.modal||ui.modal==='camp')&&!g.battle&&!ui.setup&&!ui.pass&&/^[1-4]$/.test(e.key)&&me().hand[+e.key-1])pickCard(+e.key-1);if(e.key==='Enter'&&e.target.dataset.hex)hexClick(e.target.dataset.hex);});
 // Pure state is exposed for local rule verification; all normal play goes through validated actions.
 window.DinoTable={getState:()=>E.clone(g),getUI:()=>E.clone(ui),isAnimating:()=>motionBusy||!!motionFrame||!!window.DinoMotion?.isAnimating()};
 render();
